#include "NCLGLVertexFragmentProgram.h"

NCLGLVertexFragmentProgram::NCLGLVertexFragmentProgram(   ) {
    _precision = "precision highp float;\n\nprecision highp int;\n\n";
    version = "#version 300 es \n ";
    enabled = true;
    //this.onpre = null;
    //this.onpost = null;
    viewSource = false;
}

void NCLGLVertexFragmentProgram::init(std::string *name, std::vector<std::string> arrOutput,
                                         uint8_t *drawMode, uint8_t *depthTest, uint8_t *blend,
                                         std::string blendEquation, std::string blendSrcMode, std::string blendDstMode,
                                         std::string vertexHeader, std::string vertexSource,
                                         std::vector<std::string> v_varname, std::vector<std::string> v_varnameC, std::vector<std::string> v_type, std::vector<std::string> v_expectedMode, int v_inValuesCount,
                                         std::string fragmentHeader, std::string fragmentSource,
                                         std::vector<std::string> f_varname, std::vector<std::string> f_varnameC, std::vector<std::string> f_type, std::vector<std::string> f_expectedMode, int f_inValuesCount) {
    _name = std::string(*name);
    _depthTest = *depthTest;
    _blend = *blend;
    _blendSrcMode = getEnumBlendMode(&blendSrcMode);
    _blendDstMode = getEnumBlendMode(&blendDstMode);
    _blendEquation = GL_FUNC_ADD;

    _v_inValuesCount = int(v_inValuesCount);
    _f_inValuesCount = int(f_inValuesCount);

    _output = arrOutput; //String or Array<String> of arg names with the items in same order that in the final return

    //this.fBuffer = null;
    //this.fBufferTemp = null;

    _drawMode = *drawMode;

    setVertexSource(vertexHeader, vertexSource, v_varname, v_varnameC, v_type, v_expectedMode);

    setFragmentSource(fragmentHeader, fragmentSource, f_varname, f_varnameC, f_type, f_expectedMode);

    compile();
}


GLuint NCLGLVertexFragmentProgram::getEnumBlendMode(std::string *blendStr) {
    GLuint blendMode = GL_ONE;
    if(strcmp(blendStr->c_str(), "ZERO")==0)
        blendMode = GL_ZERO;
    else if(strcmp(blendStr->c_str(), "ONE")==0)
        blendMode = GL_ONE;
    else if(strcmp(blendStr->c_str(), "SRC_COLOR")==0)
        blendMode = GL_SRC_COLOR;
    else if(strcmp(blendStr->c_str(), "ONE_MINUS_SRC_COLOR")==0)
        blendMode = GL_ONE_MINUS_SRC_COLOR;
    else if(strcmp(blendStr->c_str(), "DST_COLOR")==0)
        blendMode = GL_DST_COLOR;
    else if(strcmp(blendStr->c_str(), "ONE_MINUS_DST_COLOR")==0)
        blendMode = GL_ONE_MINUS_DST_COLOR;
    else if(strcmp(blendStr->c_str(), "SRC_ALPHA")==0)
        blendMode = GL_SRC_ALPHA;
    else if(strcmp(blendStr->c_str(), "ONE_MINUS_SRC_ALPHA")==0)
        blendMode = GL_ONE_MINUS_SRC_ALPHA;
    else if(strcmp(blendStr->c_str(), "DST_ALPHA")==0)
        blendMode = GL_DST_ALPHA;
    else if(strcmp(blendStr->c_str(), "ONE_MINUS_DST_ALPHA")==0)
        blendMode = GL_ONE_MINUS_DST_ALPHA;
    else if(strcmp(blendStr->c_str(), "SRC_ALPHA_SATURATE")==0)
        blendMode = GL_SRC_ALPHA_SATURATE;
    else if(strcmp(blendStr->c_str(), "CONSTANT_COLOR")==0)
        blendMode = GL_CONSTANT_COLOR;
    else if(strcmp(blendStr->c_str(), "ONE_MINUS_CONSTANT_COLOR")==0)
        blendMode = GL_ONE_MINUS_CONSTANT_COLOR;
    else if(strcmp(blendStr->c_str(), "CONSTANT_ALPHA")==0)
        blendMode = GL_CONSTANT_ALPHA;
    else if(strcmp(blendStr->c_str(), "ONE_MINUS_CONSTANT_ALPHA")==0)
        blendMode = GL_ONE_MINUS_CONSTANT_ALPHA;

    return blendMode;
};

/**
 * lines_fragment_attrs
 * @param {Object} values
 */
std::string NCLGLVertexFragmentProgram::lines_header(NCLGLPgrInValue in_values[], int *count) {
    std::string str;
    for(int n=0; n < *count; n++) {
        if(strcmp(in_values[n].type.c_str(), "float4_fromSampler")==0)
            str = str+"uniform sampler2D "+in_values[n].varnameC+";";
        else if(strcmp(in_values[n].type.c_str(), "float_fromSampler")==0)
            str = str+"uniform sampler2D "+in_values[n].varnameC+";";
        else if(strcmp(in_values[n].type.c_str(), "float4_fromAttr")==0)
            str = str+"in vec4 "+in_values[n].varnameC+";";
        else if(strcmp(in_values[n].type.c_str(), "float_fromAttr")==0)
            str = str+"in float "+in_values[n].varnameC+";";
        else if(strcmp(in_values[n].type.c_str(), "float")==0)
            str = str+"uniform float "+in_values[n].varnameC+";";
        else if(strcmp(in_values[n].type.c_str(), "float4")==0)
            str = str+"uniform vec4 "+in_values[n].varnameC+";";
        else if(strcmp(in_values[n].type.c_str(), "mat4")==0)
            str = str+"uniform mat4 "+in_values[n].varnameC+";";
    }
    return str;
};

/**
 * get_global_id3_GLSLFunctionString
 */
std::string NCLGLVertexFragmentProgram::get_global_id3_GLSLFunctionString() {
    std::string str = "";
    return str+"vec2 get_global_id(float id, float bufferWidth, float geometryLength) {\n"+
                "float texelSize = 1.0/bufferWidth;"+

                "float num = (id*geometryLength)/bufferWidth;"+
                "float column = fract(num)+(texelSize/2.0);"+
                "float row = (floor(num)/bufferWidth)+(texelSize/2.0);"+

                "return vec2(column, row);"+
            "}\n";
};
/**
 * get_global_id2_GLSLFunctionString
 */
std::string NCLGLVertexFragmentProgram::get_global_id2_GLSLFunctionString() {
    std::string str = "";
    return str+"vec2 get_global_id(vec2 id, float bufferWidth) {\n"+
                "float texelSize = 1.0/bufferWidth;"+

                "float column = (id.x/bufferWidth)+(texelSize/2.0);"+
                "float row = (id.y/bufferWidth)+(texelSize/2.0);"+

                "return vec2(column, row);"+
           "}\n";
};
std::string NCLGLVertexFragmentProgram::lines_drawBuffersWriteInit_GL2() {
    std::string str = "";
    for(int n=0; n < 8; n++)
        str = str+"layout(location = "+std::to_string(n)+") out vec4 outCol"+std::to_string(n)+";\n";

    return str;
};
std::string NCLGLVertexFragmentProgram::lines_drawBuffersInit() {
    std::string str = "";
    for(int n=0; n < 8; n++)
        str = str+"float out"+std::to_string(n)+"_float = -999.99989;\n"+
                    "vec4 out"+std::to_string(n)+"_float4;\n";

    return str;
};
std::string NCLGLVertexFragmentProgram::lines_drawBuffersWrite_GL2() {
    std::string str = "";
    for(int n=0; n < 8; n++)
        str = str+"if(out"+std::to_string(n)+"_float != -999.99989) outCol"+std::to_string(n)+" = vec4(out"+std::to_string(n)+"_float,0.0,0.0,1.0);\n"+
               " else outCol"+std::to_string(n)+" = out"+std::to_string(n)+"_float4;\n";

    return str;
};
void NCLGLVertexFragmentProgram::compile() {
    std::string sourceVertex = 	version+
        _precision+
        "uniform float uOffset;\n"+
        "uniform float uBufferWidth;"+

            lines_header(in_vertex_values, &_v_inValuesCount)+

        //WebCLGLUtils.unpackGLSLFunctionString()+

        get_global_id3_GLSLFunctionString()+
        get_global_id2_GLSLFunctionString()+

        _vertexHead+

        "void main(void) {\n"+
            _vertexSource+
        "}\n";
    std::string sourceFragment = version+
        _precision+

            lines_header(in_fragment_values, &_f_inValuesCount)+

        get_global_id3_GLSLFunctionString()+
        get_global_id2_GLSLFunctionString()+

        _fragmentHead+

        lines_drawBuffersWriteInit_GL2()+
        "void main(void) {\n"+
            lines_drawBuffersInit()+

            _fragmentSource+

            lines_drawBuffersWrite_GL2()+
        "}\n";

    pgr_vertexFragment = glCreateProgram();
    // utils.createShader
    GLuint vertexShader = NCLGLUtils::compileShader(GL_VERTEX_SHADER, &sourceVertex);
    GLuint fragmentShader = NCLGLUtils::compileShader(GL_FRAGMENT_SHADER, &sourceFragment);
    glAttachShader(pgr_vertexFragment, vertexShader);
    glAttachShader(pgr_vertexFragment, fragmentShader);

    glLinkProgram(pgr_vertexFragment);
    glValidateProgram(pgr_vertexFragment);

    printf("[NCLGLVertexFragmentProgram compile] compiled! \n");

    // locs
    uOffset = glGetUniformLocation(pgr_vertexFragment, "uOffset");
    uBufferWidth = glGetUniformLocation(pgr_vertexFragment, "uBufferWidth");

    for(int n=0; n < _v_inValuesCount; n++) {
        GLint loc = (strcmp(in_vertex_values[n].expectedMode.c_str(), "ATTRIBUTE")==0) // ATTRIBUTE
                ? glGetAttribLocation(pgr_vertexFragment, in_vertex_values[n].varname.c_str())
                : glGetUniformLocation(pgr_vertexFragment, in_vertex_values[n].varname.c_str());
        in_vertex_values[n].location = loc;
    }

    for(int n=0; n < _f_inValuesCount; n++) {
        in_fragment_values[n].location = glGetUniformLocation(pgr_vertexFragment, in_fragment_values[n].varname.c_str());
    }

    //return "VERTEX PROGRAM\n"+sourceVertex+"\n FRAGMENT PROGRAM\n"+sourceFragment;
}

void NCLGLVertexFragmentProgram::setVertexSource(std::string header, std::string source, std::vector<std::string> varname, std::vector<std::string> varnameC, std::vector<std::string> type, std::vector<std::string> expectedMode) {
    _vertexHead = std::string(header);
    _vertexSource = std::string(source);

    for(int n=0; n < _v_inValuesCount; n++) {
        in_vertex_values[n] = NCLGLPgrInValue();
        in_vertex_values[n].varname = varname[n];
        in_vertex_values[n].varnameC = varnameC[n];
        in_vertex_values[n].type = type[n];
        in_vertex_values[n].expectedMode = expectedMode[n];
        //in_vertex_values[n].location = nullptr;
    }
}

void NCLGLVertexFragmentProgram::setFragmentSource(std::string header, std::string source, std::vector<std::string> varname, std::vector<std::string> varnameC, std::vector<std::string> type, std::vector<std::string> expectedMode) {
    _fragmentHead = std::string(header);
    _fragmentSource = std::string(source);

    for(int n=0; n < _f_inValuesCount; n++) {
        in_fragment_values[n] = NCLGLPgrInValue();
        in_fragment_values[n].varname = varname[n];
        in_fragment_values[n].varnameC = varnameC[n];
        in_fragment_values[n].type = type[n];
        in_fragment_values[n].expectedMode = expectedMode[n];
        //in_fragment_values[n].location = nullptr;
    }
}

NCLGLVertexFragmentProgram::~NCLGLVertexFragmentProgram (void) {

}